DROP TABLE IF EXISTS `daily_health_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_health_records` (
  `record_id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `record_date` date NOT NULL COMMENT '记录日期',
  `total_sugar_intake` float DEFAULT '0' COMMENT '当日总糖分摄入(g)',
  `total_calories` float DEFAULT '0' COMMENT '当日总热量摄入(kcal)',
  `water_intake` float DEFAULT '0' COMMENT '当日饮水量(ml)',
  `exercise_minutes` float DEFAULT '0' COMMENT '当日运动时长(分钟)',
  `sleep_hours` float DEFAULT NULL COMMENT '睡眠时长(小时)',
  `systolic_bp` float DEFAULT NULL COMMENT '收缩压(mmHg)',
  `diastolic_bp` float DEFAULT NULL COMMENT '舒张压(mmHg)',
  `blood_glucose` float DEFAULT NULL COMMENT '血糖(mmol/L)',
  `weight` float DEFAULT NULL COMMENT '体重(kg)',
  `mood` enum('excellent','good','normal','bad','terrible') DEFAULT NULL COMMENT '心情',
  `notes` text COMMENT '备注',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`record_id`),
  UNIQUE KEY `uk_user_date` (`user_id`,`record_date`),
  KEY `idx_user` (`user_id`),
  KEY `idx_date` (`record_date`)
) ENGINE=InnoDB AUTO_INCREMENT=459 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日健康记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

