--
-- Table structure for table `drinks`
--

DROP TABLE IF EXISTS `drinks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drinks` (
  `drink_id` int NOT NULL AUTO_INCREMENT COMMENT '饮品ID',
  `drink_name` varchar(100) NOT NULL COMMENT '饮品名称',
  `brand` varchar(100) DEFAULT NULL COMMENT '品牌',
  `category` varchar(50) DEFAULT NULL COMMENT '类别（茶饮/咖啡/奶茶/果汁/碳酸饮料等）',
  `sugar_content` float NOT NULL COMMENT '含糖量(g/100ml)',
  `calories` float NOT NULL COMMENT '热量(kcal/100ml)',
  `volume` float DEFAULT '500' COMMENT '标准容量(ml)',
  `caffeine` float DEFAULT '0' COMMENT '咖啡因含量(mg/100ml)',
  `fat` float DEFAULT '0' COMMENT '脂肪含量(g/100ml)',
  `protein` float DEFAULT '0' COMMENT '蛋白质含量(g/100ml)',
  `sodium` float DEFAULT '0' COMMENT '钠含量(mg/100ml)',
  `health_score` int DEFAULT '50' COMMENT '健康评分(0-100)',
  `ingredients` text COMMENT '配料表',
  `allergens` varchar(200) DEFAULT NULL COMMENT '过敏原信息',
  `image_url` varchar(500) DEFAULT NULL COMMENT '图片URL',
  `source_url` varchar(500) DEFAULT NULL COMMENT '信息来源URL',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`drink_id`),
  KEY `idx_name` (`drink_name`),
  KEY `idx_brand` (`brand`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='饮品信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
