--
-- Table structure for table `food_nutrition`
--

DROP TABLE IF EXISTS `food_nutrition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `food_nutrition` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `food_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '食品名称',
  `caloric_value` decimal(10,3) DEFAULT '0.000' COMMENT '热量值 (kcal/100g)',
  `fat` decimal(10,3) DEFAULT '0.000' COMMENT '脂肪 (g/100g)',
  `saturated_fats` decimal(10,3) DEFAULT '0.000' COMMENT '饱和脂肪 (g/100g)',
  `monounsaturated_fats` decimal(10,3) DEFAULT '0.000' COMMENT '单不饱和脂肪 (g/100g)',
  `polyunsaturated_fats` decimal(10,3) DEFAULT '0.000' COMMENT '多不饱和脂肪 (g/100g)',
  `carbohydrates` decimal(10,3) DEFAULT '0.000' COMMENT '碳水化合物 (g/100g)',
  `sugars` decimal(10,3) DEFAULT '0.000' COMMENT '糖分 (g/100g)',
  `protein` decimal(10,3) DEFAULT '0.000' COMMENT '蛋白质 (g/100g)',
  `dietary_fiber` decimal(10,3) DEFAULT '0.000' COMMENT '膳食纤维 (g/100g)',
  `cholesterol` decimal(10,3) DEFAULT '0.000' COMMENT '胆固醇 (mg/100g)',
  `sodium` decimal(10,3) DEFAULT '0.000' COMMENT '钠 (g/100g)',
  `water` decimal(10,3) DEFAULT '0.000' COMMENT '水分 (g/100g)',
  `vitamin_a` decimal(10,3) DEFAULT '0.000' COMMENT '维生素A (mg/100g)',
  `vitamin_b1` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B1 (mg/100g)',
  `vitamin_b11` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B11 (mg/100g)',
  `vitamin_b12` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B12 (mg/100g)',
  `vitamin_b2` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B2 (mg/100g)',
  `vitamin_b3` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B3 (mg/100g)',
  `vitamin_b5` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B5 (mg/100g)',
  `vitamin_b6` decimal(10,3) DEFAULT '0.000' COMMENT '维生素B6 (mg/100g)',
  `vitamin_c` decimal(10,3) DEFAULT '0.000' COMMENT '维生素C (mg/100g)',
  `vitamin_d` decimal(10,3) DEFAULT '0.000' COMMENT '维生素D (mg/100g)',
  `vitamin_e` decimal(10,3) DEFAULT '0.000' COMMENT '维生素E (mg/100g)',
  `vitamin_k` decimal(10,3) DEFAULT '0.000' COMMENT '维生素K (mg/100g)',
  `calcium` decimal(10,3) DEFAULT '0.000' COMMENT '钙 (mg/100g)',
  `copper` decimal(10,3) DEFAULT '0.000' COMMENT '铜 (mg/100g)',
  `iron` decimal(10,3) DEFAULT '0.000' COMMENT '铁 (mg/100g)',
  `magnesium` decimal(10,3) DEFAULT '0.000' COMMENT '镁 (mg/100g)',
  `manganese` decimal(10,3) DEFAULT '0.000' COMMENT '锰 (mg/100g)',
  `phosphorus` decimal(10,3) DEFAULT '0.000' COMMENT '磷 (mg/100g)',
  `potassium` decimal(10,3) DEFAULT '0.000' COMMENT '钾 (mg/100g)',
  `selenium` decimal(10,3) DEFAULT '0.000' COMMENT '硒 (mg/100g)',
  `zinc` decimal(10,3) DEFAULT '0.000' COMMENT '锌 (mg/100g)',
  `nutrition_density` decimal(10,3) DEFAULT '0.000' COMMENT '营养密度',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_food_name` (`food_name`),
  KEY `idx_caloric_value` (`caloric_value`),
  KEY `idx_sugars` (`sugars`)
) ENGINE=InnoDB AUTO_INCREMENT=2396 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食品营养成分数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

