  `category` varchar(50) DEFAULT NULL COMMENT '分类（营养/疾病/运动/饮食等）',
  `tags` varchar(200) DEFAULT NULL COMMENT '标签（逗号分隔）',
  `source` varchar(200) DEFAULT NULL COMMENT '来源',
  `reliability_score` int DEFAULT '70' COMMENT '可信度评分(0-100)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`knowledge_id`),
  KEY `idx_category` (`category`),
  FULLTEXT KEY `idx_content` (`title`,`content`)
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='健康知识库表';
/*!40101 SET character_set_client = @saved_cs_client */;

